use mip_codex::{mps,heuristic::Repair,solve::Result};
fn main(){let a:Vec<_>=std::env::args().collect();if a.get(1).is_some_and(|v|v=="build-info"){println!("{}",serde_json::json!({"source_directory":env!("CARGO_MANIFEST_DIR"),"source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT,"library_source_directory":mip_codex::BUILD_SOURCE_DIRECTORY,"library_source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT}));return;}let m=mps::read(&a[1]).unwrap();let lo:Vec<_>=m.variables.iter().map(|v|v.lower).collect();let hi:Vec<_>=m.variables.iter().map(|v|v.upper).collect();let start=vec![0.;m.variables.len()];let mut repair=Repair::new(&m);let began=std::time::Instant::now();let x=repair.search(&start,&lo,&hi,began+std::time::Duration::from_secs(2),1_000_000,7);let valid=x.as_ref().is_none_or(|v|repair.candidate_check(v));assert!(valid);let r=Result{status:if x.is_some(){"feasible"}else{"unknown"}.into(),objective:x.as_ref().map(|v|m.objective(v)),values:x.map(|v|m.variables.iter().zip(v).map(|(v,x)|(v.name.clone(),x)).collect()),seconds:began.elapsed().as_secs_f64(),..Result::default()};println!("{}",serde_json::json!({"result":r,"work":repair.stats.work,"moves":repair.stats.moves}));}
